            wait = route.waits[enemy.route_wait_index]
            if start - self._EPSILON <= wait.distance <= proposed + self._EPSILON:
                enemy.distance = wait.distance
                enemy.route_wait_index += 1
                enemy.route_wait_remaining = wait.duration
