                self._emit(state, EventType.ENEMY_LEAK, source=enemy.instance_id, amount=enemy.life_point_reduce)
            else:
                self._emit(state, EventType.PROTECTED_TARGET_REACHED, source=enemy.instance_id, amount=0)
